#!/usr/bin/env bash
# Thin wrapper: materialize rewriter (if needed) and run it.
set -euo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT"
PY="$ROOT/scripts/make-urls-relative.py"
# Always refresh from embedded payload so MCP/partial pushes stay consistent.
PAYLOAD=''
echo "$PAYLOAD" | base64 -d | gzip -d > "$PY"
chmod +x "$PY"
exec python3 "$PY" "$@"
